function pointPreview(){const balance=support.wallet?.balance||0;const amount=Math.floor(balance*percentage/100);$('point-wallet').textContent='내 사용 가능 포인트 '+balance.toLocaleString()+'P';$('point-amount').textContent=percentage+'% · '+amount.toLocaleString()+'P';$('point-allocation').textContent=support.has_prior_supporters?'저자 약 '+(amount-Math.floor(amount*.3))+'P · 선행 지지자 최대 '+Math.floor(amount*.3)+'P':'선행 지지자가 없어 저자가 '+amount+'P를 받습니다.';$('support-confirm').disabled=!support.can_support||!amount;$('support-confirm').textContent=amount.toLocaleString()+'P 지지 투자 확정';$('point-options').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.percent)===percentage)));}
async function supportDialog(){if(!signedIn){location.href='/login';return;}await loadSupport();const options=$('point-options');options.replaceChildren();[1,5,10,25,50,100].forEach(p=>{const b=el('button','secondary',p+'%');b.dataset.percent=p;b.onclick=()=>{if(supportBusy)return;percentage=p;supportAttempt=null;pointPreview();};options.append(b);});['point-options','point-amount','point-allocation','support-confirm'].forEach(id=>$(id).hidden=!support.can_support);percentage=10;supportAttempt=null;pointPreview();notice($('support-notice'),support.can_support?'':selected.can_publish?'자신의 글에는 투자할 수 없습니다. 다른 사람의 지지로 포인트를 받을 수 있습니다.':'공개된 글에 지지할 수 있습니다.');$('support-dialog').showModal();}
